function searchBar(withType=false,companies=[]){return `<div class="filters">${withType?`<label>문서 유형 <select id="type-filter"><option value="">전체 문서</option>${options()}</select></label><label>시작일 <input id="document-from" type="date" value="${esc(state.documentFrom)}"></label><label>종료일 <input id="document-to" type="date" value="${esc(state.documentTo)}"></label><button type="button" data-date-preset="yesterday">어제</button><button type="button" data-date-preset="today">오늘</button><button type="button" data-date-preset="month">이번 달</button>`:''}${withType&&state.type==='risk'?`<label>평가 종류 <select id="risk-kind-filter"><option value="">전체</option>${Object.entries(riskKinds).map(([key,label])=>`<option value="${key}" ${state.riskKind===key?'selected':''}>${esc(label)}</option>`).join('')}</select></label><label>등록 협력사 <select id="risk-company-filter"><option value="">전체</option>${companies.map(company=>`<option value="${company.id}" ${state.riskContractorId===String(company.id)?'selected':''}>${esc(company.name)}</option>`).join('')}</select></label>`:''}<input id="query" placeholder="제목 또는 내용 검색" value="${esc(state.query)}"><button id="search" class="outline">검색</button></div>`;}
