async function loadDocuments() {const scoped=['documents','approval'].includes(state.page),office=state.page==='office-documents';const params=new URLSearchParams({siteId:String(state.siteId),type:office?'office':scoped?state.type:'',q:scoped||office?state.query:'',from:scoped?state.documentFrom:'',to:scoped?state.documentTo:''});if(scoped&&state.type==='risk'){params.set('riskKind',state.riskKind);params.set('riskContractorId',state.riskContractorId);}return api(`/api/documents?${params}`);}
